(5938388, 865564, 45631, '<td valign="top">Love this shot.  One of my top pics.  Miserable gray day with hits of orange which make it interesting.  Love the composition and DOF.  Well done.</td>', 'Love this shot.  One of my top pics.  Miserable gray day with hits of orange which make it interesting.  Love the composition and DOF.  Well done.', '2010-04-09 07:22:25.000000', NULL, 1),
(5938390, 865296, 45631, '<td valign="top">Great take on this challenge.  Just one person seated really works well and the plane and others showing behind really add to the composition.  Love it in BW.  One of my top pic.</td>', 'Great take on this challenge.  Just one person seated really works well and the plane and others showing behind really add to the composition.  Love it in BW.  One of my top pic.', '2010-04-09 07:23:31.000000', NULL, 1),
