(5939173, 865647, 96751, '<td valign="top">Iconic image.  Love it.</td>', 'Iconic image.  Love it.', '2010-04-10 03:39:36.000000', NULL, 1),
(5939174, 865417, 96751, '<td valign="top">Interesting image.  The figure is very strong, but the background is not - it almost looks like a sound stage.  Nice, crisp conversion.</td>', 'Interesting image.  The figure is very strong, but the background is not - it almost looks like a sound stage.  Nice, crisp conversion.', '2010-04-10 03:41:03.000000', NULL, 1),
(5939175, 864630, 96751, '<td valign="top">Great and gritty street scene.</td>', 'Great and gritty street scene.', '2010-04-10 03:41:21.000000', NULL, 1),
(5939176, 864826, 96751, '<td valign="top">Interesting macro, but overexposed.</td>', 'Interesting macro, but overexposed.', '2010-04-10 03:41:53.000000', NULL, 1),
(5939177, 865487, 96751, '<td valign="top">Interesting abstract.</td>', 'Interesting abstract.', '2010-04-10 03:42:16.000000', NULL, 1),
(5939178, 864918, 96751, '<td valign="top">So sweet.  Love the sepia.</td>', 'So sweet.  Love the sepia.', '2010-04-10 03:42:38.000000', NULL, 1),
