(5939180, 865572, 96751, '<td valign="top">So colorful.</td>', 'So colorful.', '2010-04-10 03:43:35.000000', NULL, 1),
(5939181, 865560, 96751, '<td valign="top">I love the edges outlined in light.</td>', 'I love the edges outlined in light.', '2010-04-10 03:43:54.000000', NULL, 1),
(5939182, 865552, 96751, '<td valign="top">Terrific shot.  I love the stillness of the man and the puddle at his feet contrasted with the rush of water.</td>', 'Terrific shot.  I love the stillness of the man and the puddle at his feet contrasted with the rush of water.', '2010-04-10 03:44:22.000000', NULL, 1),
(5939183, 864259, 96751, '<td valign="top">Been there.  Done that.  Waiting - the photographer''s main activity...</td>', 'Been there.  Done that.  Waiting - the photographer''s main activity...', '2010-04-10 03:44:55.000000', NULL, 1),
(5939184, 865512, 96751, '<td valign="top">What a face!!!</td>', 'What a face!!!', '2010-04-10 03:45:27.000000', NULL, 1),
(5939185, 864791, 96751, '<td valign="top">So noble.</td>', 'So noble.', '2010-04-10 03:45:38.000000', NULL, 1),
(5939186, 865617, 96751, '<td valign="top">The stillness of the water is incredible.</td>', 'The stillness of the water is incredible.', '2010-04-10 03:45:59.000000', NULL, 1),
(5939187, 864527, 96751, '<td valign="top">I love this shot.  Great colors and clarity.  Terrific depth control.  Just a tad overblown on the right, but that''s just nitpicking.  And it doesn''t really say "waiting" to me, but I love the shot.</td>', 'I love this shot.  Great colors and clarity.  Terrific depth control.  Just a tad overblown on the right, but that''s just nitpicking.  And it doesn''t really say "waiting" to me, but I love the shot.', '2010-04-10 03:46:50.000000', NULL, 1),
(5939188, 865720, 96751, '<td valign="top">Classic, and well processed.</td>', 'Classic, and well processed.', '2010-04-10 03:47:08.000000', NULL, 1),
(5939189, 865456, 96751, '<td valign="top">This is such a sad picture.  Very emotive and well seen.  Nice conversion.</td>', 'This is such a sad picture.  Very emotive and well seen.  Nice conversion.', '2010-04-10 03:47:53.000000', NULL, 1),
(5939190, 865759, 96751, '<td valign="top">Wonderful luminosity in this slice of life.  I wonder if it might have been stronger had it been cropped to the center line of the chair on right.</td>', 'Wonderful luminosity in this slice of life.  I wonder if it might have been stronger had it been cropped to the center line of the chair on right.', '2010-04-10 03:49:00.000000', NULL, 1),
(5939191, 864530, 96751, '<td valign="top">This will probably do very well, but I can''t decide whether I like the blur or find it distracting.</td>', 'This will probably do very well, but I can''t decide whether I like the blur or find it distracting.', '2010-04-10 03:49:32.000000', NULL, 1),
(5939192, 865441, 96751, '<td valign="top">Love the implied story here.  Great lines and colors.</td>', 'Love the implied story here.  Great lines and colors.', '2010-04-10 03:49:46.000000', NULL, 1),
(5939193, 865238, 96751, '<td valign="top">What IS this?????</td>', 'What IS this?????', '2010-04-10 03:50:04.000000', NULL, 1),
