(5939195, 865746, 96751, '<td valign="top">A bit overexposed to my eye, but rather magical at the same time.</td>', 'A bit overexposed to my eye, but rather magical at the same time.', '2010-04-10 03:51:20.000000', NULL, 1),
(5939196, 865749, 96751, '<td valign="top">I love shots like this . Incredible clarity and sharpness on the static objects.</td>', 'I love shots like this . Incredible clarity and sharpness on the static objects.', '2010-04-10 03:52:06.000000', NULL, 1),
(5939197, 864658, 96751, '<td valign="top">Such an eloquent image.  Te weight of the world on his shoulders.  Fabulous conversion.  Love the slight sepia.</td>', 'Such an eloquent image.  Te weight of the world on his shoulders.  Fabulous conversion.  Love the slight sepia.', '2010-04-10 03:52:41.000000', NULL, 1),
(5939198, 865093, 96751, '<td valign="top">The sort of image that does well here.</td>', 'The sort of image that does well here.', '2010-04-10 03:53:12.000000', NULL, 1),
(5939199, 865230, 96751, '<td valign="top">Interesting trick.  Looking forward to the notes, though I suspect this is a long evening exposure.</td>', 'Interesting trick.  Looking forward to the notes, though I suspect this is a long evening exposure.', '2010-04-10 03:54:02.000000', NULL, 1),
