(5939202, 865296, 96751, '<td valign="top">Great conversion, though the content is too busy for me.  A tighter crop with just the woman and the two rows of chairs might have been stronger.</td>', 'Great conversion, though the content is too busy for me.  A tighter crop with just the woman and the two rows of chairs might have been stronger.', '2010-04-10 03:55:47.000000', NULL, 1),
(5939203, 865564, 96751, '<td valign="top">Beautiful image.  Doesn''t say "waiting" to me, but the colors, the sand texture and the blurred figure in the distance are simple yet eloquent.</td>', 'Beautiful image.  Doesn''t say "waiting" to me, but the colors, the sand texture and the blurred figure in the distance are simple yet eloquent.', '2010-04-10 03:56:50.000000', NULL, 1),
(5939204, 865198, 96751, '<td valign="top">Terrific depth and textures (though a bit overblown on the left.  Great sharpness and tonal variety.  Love it.</td>', 'Terrific depth and textures (though a bit overblown on the left.  Great sharpness and tonal variety.  Love it.', '2010-04-10 03:57:24.000000', NULL, 1),
